// Some portions generated by Codex

// @ts-check
const { test, expect } = require('@playwright/test');
const { monitorEventLoopDelay } = require('node:perf_hooks');
const fs = require('node:fs/promises');
const { serverBaseUrl, uniqueRepositoryId, workbenchBaseUrl } = require('./workbench-test-helpers.js');

const SERVER_BASE_URL = serverBaseUrl();
const WORKBENCH_BASE_URL = workbenchBaseUrl();
const REPOSITORY_ID = uniqueRepositoryId('query-timeout-after-rows');
const REPOSITORY_URL = `${SERVER_BASE_URL}/repositories/${REPOSITORY_ID}`;
const QUERY_URL = `${WORKBENCH_BASE_URL}/repositories/${REPOSITORY_ID}/query`;
const NDJSON_ACCEPT = 'application/vnd.rdf4j.workbench+ndjson';
const QUERY_TIMEOUT_SECONDS = 1;
// 200^3 = 8,000,000 candidate rows: inexpensive rows reach the transport promptly, while the large result keeps
// both tuple and graph queries active past the timeout. Expensive per-row functions can instead expire before
// the graph transport's Binary RDF statement buffer fills, producing no partial rows to exercise the renderer.
const VALUES_PER_DIMENSION = 200;
const TIMEOUT_RERUN_TEST_TITLE = 'shows partial rows on a real query timeout, cleans up, then executes again';
const diagnosticsByTest = new WeakMap();
let repositoryCreated = false;

test.beforeEach(async ({ page, browserName }, testInfo) => {
	if (testInfo.title !== TIMEOUT_RERUN_TEST_TITLE) {
		return;
	}
	diagnosticsByTest.set(testInfo, await installTimeoutDiagnostics(page, browserName));
});

test.afterEach(async ({ page }, testInfo) => {
	const diagnostics = diagnosticsByTest.get(testInfo);
	if (!diagnostics) {
		return;
	}
	await attachTimeoutDiagnostics(page, testInfo, diagnostics);
});

test.beforeAll(async ({ request }) => {
	const existing = await request.get(REPOSITORY_URL);
	if (![400, 404].includes(existing.status())) {
		throw new Error(`Refusing to use non-absent disposable repository ${REPOSITORY_ID}: GET ${existing.status()}`);
	}
	const created = await request.put(REPOSITORY_URL, {
		headers: { 'Content-Type': 'text/turtle' },
		data: repositoryConfiguration(REPOSITORY_ID)
	});
	expect([200, 201, 204]).toContain(created.status());
	repositoryCreated = true;
});

test.afterAll(async ({ request }) => {
	if (!repositoryCreated) {
		return;
	}
	const deleted = await request.delete(REPOSITORY_URL);
	expect([200, 204, 400, 404]).toContain(deleted.status());
	const absent = await request.get(REPOSITORY_URL);
	expect([400, 404]).toContain(absent.status());
	console.log(`[query-timeout-disposable-repository-cleanup] ${JSON.stringify({
		repositoryId: REPOSITORY_ID,
		deleteStatus: deleted.status(),
		followupStatus: absent.status(),
		absent: true
	})}`);
});

test('shows partial rows on a real query timeout, cleans up, then executes again', async ({ page }, testInfo) => {
	test.setTimeout(90000);
	await page.setViewportSize({ width: 390, height: 844 });
	const monitor = monitorPage(page);
	// The compact stream sends several hundred thousand rows in the one second before the timeout (about 100 MB),
	// more than Chromium's inspector keeps for response.text(), so the page keeps its own copy of the body.
	await captureQueryResponseBodies(page);
	await page.goto(QUERY_URL, { waitUntil: 'domcontentloaded' });
	await page.locator('#query-form').waitFor({ state: 'visible' });
	await page.locator('.CodeMirror').first().waitFor({ state: 'visible' });
	await page.locator('#query-options-toggle').click();
	await page.locator('#query-timeout').fill(String(QUERY_TIMEOUT_SECONDS));

	const values = Array.from({ length: VALUES_PER_DIMENSION }, (_, index) => String(index)).join(' ');
	const timeoutQuery = `SELECT ?a ?b ?c WHERE { VALUES ?a { ${values} } VALUES ?b { ${values} } `
		+ `VALUES ?c { ${values} } }`;
	await setEditor(page, timeoutQuery);
	await page.evaluate(() => {
		const root = document.getElementById('query-results');
		const metrics = {
			startedAt: performance.now(),
			firstBusyRowAt: null,
			busyRowsAtFirstPaint: 0,
			maxRowsWhileBusy: 0,
			terminalAt: null
		};
		window.__queryTimeoutMetrics = metrics;
		const observe = () => {
			const busy = root.getAttribute('aria-busy') === 'true';
			const visibleRows = root.querySelectorAll('[data-query-row-index], [data-query-record-index]').length;
			if (busy && visibleRows > 0) {
				metrics.maxRowsWhileBusy = Math.max(metrics.maxRowsWhileBusy, visibleRows);
				if (metrics.firstBusyRowAt === null) {
					metrics.firstBusyRowAt = performance.now();
					metrics.busyRowsAtFirstPaint = visibleRows;
				}
			}
			if (!busy && metrics.firstBusyRowAt !== null && metrics.terminalAt === null) {
				metrics.terminalAt = performance.now();
			}
		};
		new MutationObserver(observe).observe(root, {
			attributes: true, attributeFilter: ['aria-busy'], childList: true, subtree: true
		});
	});

	const timeoutExecutionIndex = monitor.executions.length;
	await page.locator('#exec').click();
	await expect.poll(() => monitor.executions.length - timeoutExecutionIndex).toBe(1);
	await page.waitForFunction(() => window.__queryTimeoutMetrics.firstBusyRowAt !== null,
		null, { timeout: 20000 });
	const busySnapshot = await page.evaluate(() => ({
		busy: document.getElementById('query-results').getAttribute('aria-busy'),
		visibleRows: document.querySelectorAll(
			'#query-results [data-query-row-index], #query-results [data-query-record-index]').length,
			metrics: window.__queryTimeoutMetrics
	}));
	await expect(page.locator('#query-results')).toHaveAttribute('aria-busy', 'false', { timeout: 20000 });
	const terminalMetrics = await page.evaluate(() => window.__queryTimeoutMetrics);
	await expect.poll(() => monitor.responses.length).toBeGreaterThan(timeoutExecutionIndex);
	const timeoutResponse = monitor.responses[timeoutExecutionIndex];
	await page.waitForFunction(index => window.__queryTimeoutCapturedResponses[index]
		&& window.__queryTimeoutCapturedResponses[index].complete, timeoutExecutionIndex, { timeout: 20000 });
	const streamRecords = await capturedStreamRecords(page, timeoutExecutionIndex);
	const timeoutRecord = streamRecords.find(record => record.type === 'error');
	const result = page.locator('#query-results .query-result-layout');
	const status = result.locator('.query-result-status');
	const countLabel = result.locator('.query-result-navigation__label').first();
	const downloadToggle = result.locator('.query-result-toolbar__disclosures .workbench-disclosure__toggle')
		.filter({ hasText: 'Download' });
	// The alert is a callout (icon and body) since the result states redesign (fa6a07914c); its message is the
	// .query-result-error__message line, so the wrapping is measured there and the callout must not overflow either.
	const alertMessage = page.locator('#query-results [role="alert"] .query-result-error__message');
	const alertLayout = await alertMessage.evaluate(element => ({
		clientWidth: element.clientWidth,
		scrollWidth: element.scrollWidth,
		alertClientWidth: element.closest('[role="alert"]').clientWidth,
		alertScrollWidth: element.closest('[role="alert"]').scrollWidth,
		whiteSpace: getComputedStyle(element).whiteSpace,
		text: element.textContent
	}));
	const alertWrapping = await alertMessage.evaluate(element => {
		const originalText = element.textContent;
		const longMessage = `First line.\n${'x'.repeat(512)}`;
		element.textContent = longMessage;
		const range = document.createRange();
		range.selectNodeContents(element);
		const result = {
			clientWidth: element.clientWidth,
			scrollWidth: element.scrollWidth,
			alertClientWidth: element.closest('[role="alert"]').clientWidth,
			alertScrollWidth: element.closest('[role="alert"]').scrollWidth,
			whiteSpace: getComputedStyle(element).whiteSpace,
			lineFragments: range.getClientRects().length,
			text: element.textContent
		};
		element.textContent = originalText;
		return result;
	});

	// Attach the real wire and paint evidence before the assertions, so a red run
	// records whether rows reached the DOM before the evaluator emitted its error.
	const timeoutEvidence = {
		queryUrl: QUERY_URL,
		queryTimeoutSeconds: QUERY_TIMEOUT_SECONDS,
		valuesPerDimension: VALUES_PER_DIMENSION,
		cartesianRows: VALUES_PER_DIMENSION ** 3,
		busySnapshot,
		terminalMetrics,
		response: {
			status: timeoutResponse.status,
			contentType: timeoutResponse.contentType,
			recordCounts: countRecords(streamRecords),
			terminal: summarizeRecord(streamRecords[streamRecords.length - 1])
		},
		visibleStatus: await status.textContent(),
		visibleError: await page.locator('#query-results [role="alert"]').textContent(),
		alertLayout,
		alertWrapping,
		countLabel: { visible: await countLabel.isVisible(), text: await countLabel.textContent() },
		downloadToggleVisible: await downloadToggle.isVisible(),
		busyAfterTimeout: await page.locator('#query-results').getAttribute('aria-busy'),
		cancelAfterTimeout: {
			disabled: await page.locator('#query-cancel').isDisabled(),
			ariaHidden: await page.locator('#query-cancel').getAttribute('aria-hidden'),
			requestId: await page.locator('#query-request-id').inputValue(),
			resultCancelVisible: await result.getByRole('button', { name: 'Cancel query' }).isVisible()
		}
	};
	console.log(`[query-timeout-after-rows] ${JSON.stringify(timeoutEvidence)}`);
	await testInfo.attach('query-timeout-after-rows.json', {
		body: Buffer.from(JSON.stringify(timeoutEvidence, null, 2)),
		contentType: 'application/json'
	});

	expect(busySnapshot.busy).toBe('true');
	expect(busySnapshot.visibleRows, 'the page should display partial rows before the response terminates').toBeGreaterThan(0);
	expect(terminalMetrics.firstBusyRowAt).toBeLessThan(terminalMetrics.terminalAt);
	expect(timeoutRecord, 'the real evaluator should terminate the stream with a typed error').toBeTruthy();
	expect(timeoutRecord.code).toBe('timeout');
	expect(timeoutRecord.message).toMatch(/timed out after 1 second/i);
	expect(streamRecords.some(record => record.type === 'end'), 'an interrupted stream must not claim completion').toBe(false);
	expect(streamRecords.some(record => record.metadata
		&& Object.prototype.hasOwnProperty.call(record.metadata, 'total-result-count')),
		'an interrupted stream must not publish a completion-only full count').toBe(false);
	await expect(status).toContainText(/Partial results: \d+ rows received before the query timed out\./);
	await expect(page.locator('#query-results [role="alert"]'))
		.toContainText(/Increase the timeout in Query settings and run it again\./);
	expect(alertLayout.scrollWidth, 'the full timeout recovery instruction must fit the mobile alert').toBeLessThanOrEqual(
		alertLayout.clientWidth
	);
	expect(alertLayout.alertScrollWidth, 'the timeout callout must fit the mobile result').toBeLessThanOrEqual(
		alertLayout.alertClientWidth
	);
	expect(alertLayout.whiteSpace).toBe('pre-wrap');
	expect(alertWrapping.scrollWidth, 'a long uninterrupted token must wrap inside the mobile alert')
		.toBeLessThanOrEqual(alertWrapping.clientWidth);
	expect(alertWrapping.alertScrollWidth, 'a long uninterrupted token must wrap inside the mobile alert')
		.toBeLessThanOrEqual(alertWrapping.alertClientWidth);
	expect(alertWrapping.text).toBe(`First line.\n${'x'.repeat(512)}`);
	expect(alertWrapping.lineFragments, 'preserved line breaks and long-token wrapping should occupy separate lines')
		.toBeGreaterThan(1);
	await expect(page.locator('#query-results [role="alert"]')).not.toContainText(/QueryEvaluationException|EOFException/);
	expect.soft(timeoutEvidence.countLabel.visible && /(?:total rows|Page \d+ of \d+)/i.test(timeoutEvidence.countLabel.text))
		.toBe(false);
	expect.soft(timeoutEvidence.downloadToggleVisible,
		'an incomplete result must not offer a completion-only download').toBe(false);
	await expect(page.locator('#query-results')).toHaveAttribute('aria-busy', 'false');
	await expect(page.locator('#query-cancel')).toBeDisabled();
	await expect(page.locator('#query-cancel')).toHaveAttribute('aria-hidden', 'true');
	await expect(page.locator('#query-request-id')).toHaveValue('');
	expect(timeoutEvidence.cancelAfterTimeout.resultCancelVisible).toBe(false);
	expect(monitor.executions[timeoutExecutionIndex].accept).toContain(NDJSON_ACCEPT);
	expect(monitor.errors).toEqual([]);

	const successfulExecutionIndex = monitor.executions.length;
	await page.evaluate(acceptType => {
		window.__queryTimeoutCapturedResponses = [];
		const originalFetch = window.fetch.bind(window);
		window.fetch = (input, init) => originalFetch(input, init).then(response => {
			const headers = new Headers(init && init.headers || {});
			if (init && init.method === 'POST' && (headers.get('Accept') || '').includes(acceptType)) {
				const entry = { status: response.status, body: '', complete: false };
				window.__queryTimeoutCapturedResponses.push(entry);
				response.clone().text().then(body => {
					entry.body = body;
					entry.complete = true;
				}).catch(error => {
					entry.body = `Unable to capture response: ${error.message}`;
					entry.complete = true;
				});
			}
			return response;
		});
	}, NDJSON_ACCEPT);
	await setEditor(page, timeoutQuery + ' LIMIT 1');
	await page.locator('#exec').click();
	await expect.poll(() => monitor.executions.length - successfulExecutionIndex).toBe(1);
	const successfulRerunCompleted = await page.waitForFunction(
		() => document.getElementById('query-results').getAttribute('aria-busy') === 'false',
		null,
		{ timeout: 30000 }
	).then(() => true, () => false);
	const rerunStream = await page.evaluate(() => window.__queryTimeoutCapturedResponses[0] || null);
	const rerunResponses = monitor.responses.slice(successfulExecutionIndex);
	const rerunEvidence = {
		completed: successfulRerunCompleted,
		busy: await page.locator('#query-results').getAttribute('aria-busy'),
		status: await page.locator('#query-results .query-result-status').textContent(),
		alert: await page.locator('#query-results [role="alert"]').textContent(),
		requestId: await page.locator('#query-request-id').inputValue(),
		request: monitor.executions[successfulExecutionIndex],
		capturedStream: rerunStream && {
			status: rerunStream.status,
			complete: rerunStream.complete,
			terminal: summarizeTerminalSafely(rerunStream.body),
			bodyReadError: rerunStream.body.startsWith('Unable to capture response:') ? rerunStream.body : null
		},
		responses: rerunResponses.map(response => ({
			status: response.status,
			contentType: response.contentType,
			bodyReceived: Boolean(response.body),
			bodyReadError: response.body.startsWith('Unable to read response:') ? response.body : null,
			terminal: summarizeTerminalSafely(response.body)
		})),
		pageErrors: monitor.errors
	};
	console.log(`[query-timeout-rerun] ${JSON.stringify(rerunEvidence)}`);
	await testInfo.attach('query-timeout-rerun.json', {
		body: Buffer.from(JSON.stringify(rerunEvidence, null, 2)),
		contentType: 'application/json'
	});
	expect(successfulRerunCompleted, 'a clean successful run should work immediately after timeout').toBe(true);
	// At 390 px Auto shows three columns as records (cards), so the one row is counted in either layout.
	await expect(page.locator('#query-results [data-query-row-index], #query-results [data-query-record-index]'))
		.toHaveCount(1);
	// The status counts rows and names the elapsed time (result states redesign, fa6a07914c).
	await expect(page.locator('#query-results .query-result-status')).toHaveText(/^1 row · complete in [\d,]+ ms$/);
	await expect(page.locator('#query-results [role="alert"]')).toBeHidden();
	await expect(page.locator('#query-results .query-result-toolbar__disclosures .workbench-disclosure__toggle')
		.filter({ hasText: 'Download' })).toBeVisible();
	await expect(page.locator('#query-cancel')).toBeDisabled();
	await expect(page.locator('#query-request-id')).toHaveValue('');
	expect(monitor.executions).toHaveLength(2);
	expect(monitor.executions.every(execution => execution.accept.includes(NDJSON_ACCEPT))).toBe(true);
	expect(monitor.errors).toEqual([]);
});

test('construct timeout leaves visibly incomplete graph statements without download or totals', async ({ page }, testInfo) => {
	test.setTimeout(90000);
	const monitor = monitorPage(page);
	await captureQueryResponseBodies(page);
	await page.goto(QUERY_URL, { waitUntil: 'domcontentloaded' });
	await page.locator('#query-form').waitFor({ state: 'visible' });
	await page.locator('.CodeMirror').first().waitFor({ state: 'visible' });
	await page.locator('#query-options-toggle').click();
	await page.locator('#query-timeout').fill(String(QUERY_TIMEOUT_SECONDS));

	const subjects = valuesIris('s', VALUES_PER_DIMENSION);
	const predicates = valuesIris('p', VALUES_PER_DIMENSION);
	const objects = valuesIris('o', VALUES_PER_DIMENSION);
	const constructQuery = `CONSTRUCT { ?s ?p ?o } WHERE { VALUES ?s { ${subjects} } `
		+ `VALUES ?p { ${predicates} } VALUES ?o { ${objects} } }`;
	await setEditor(page, constructQuery);
	await page.evaluate(() => {
		const root = document.getElementById('query-results');
		window.__constructTimeoutRowsWhileBusy = 0;
		new MutationObserver(() => {
			if (root.getAttribute('aria-busy') === 'true') {
				window.__constructTimeoutRowsWhileBusy = Math.max(window.__constructTimeoutRowsWhileBusy,
					root.querySelectorAll('[data-query-row-index], [data-query-record-index]').length);
			}
		}).observe(root, { attributes: true, childList: true, subtree: true });
	});

	const executionIndex = monitor.executions.length;
	await page.locator('#exec').click();
	await expect.poll(() => monitor.executions.length - executionIndex).toBe(1);
	await page.waitForFunction(() => window.__constructTimeoutRowsWhileBusy > 0, null, { timeout: 20000 })
		.catch(async error => {
			try {
				const progress = await page.evaluate(index => {
					const root = document.getElementById('query-results');
					const response = window.__queryTimeoutCapturedResponses[index];
					const records = response && response.complete ? response.body.split(/\r?\n/)
						.filter(line => line.trim()).map(line => JSON.parse(line))
						.filter(record => !Array.isArray(record)) : [];
					const terminal = records[records.length - 1];
					return {
						rowsWhileBusy: window.__constructTimeoutRowsWhileBusy,
						renderedRows: root.querySelectorAll('[data-query-row-index], [data-query-record-index]').length,
						busy: root.getAttribute('aria-busy'),
						status: root.querySelector('.query-result-status')?.textContent,
						responseComplete: !!response && response.complete,
						streamRows: records.filter(record => record.type === 'rows')
							.reduce((total, record) => total + record.values.length, 0),
						terminal: terminal && { type: terminal.type, code: terminal.code, status: terminal.status }
					};
				}, executionIndex);
				const evidence = { ...progress, pageErrors: monitor.errors };
				console.log(`[query-timeout-construct-progress-failure] ${JSON.stringify(evidence)}`);
				await testInfo.attach('query-timeout-construct-progress-failure.json', {
					body: Buffer.from(JSON.stringify(evidence, null, 2)),
					contentType: 'application/json'
				});
			} catch (diagnosticError) {
				console.log(`[query-timeout-construct-progress-diagnostic-error] ${String(diagnosticError)}`);
			}
			throw error;
		});
	const graphTimeoutCompleted = await page.waitForFunction(
		() => document.getElementById('query-results').getAttribute('aria-busy') === 'false',
		null,
		{ timeout: 30000 }
	).then(() => true, () => false);
	await expect.poll(() => monitor.responses.length).toBeGreaterThan(executionIndex);
	const response = monitor.responses[executionIndex];
	await page.waitForFunction(index => window.__queryTimeoutCapturedResponses[index]
		&& window.__queryTimeoutCapturedResponses[index].complete, executionIndex, { timeout: 20000 });
	const wireResponse = await page.evaluate(index => window.__queryTimeoutCapturedResponses[index], executionIndex);
	const records = parseNdjson(wireResponse.body);
	const view = records.find(record => record.type === 'view');
	const rows = records.filter(record => record.type === 'rows')
		.reduce((total, record) => total + record.values.length, 0);
	const terminal = records[records.length - 1] || {};
	const result = page.locator('#query-results .query-result-layout');
	const status = await result.locator('.query-result-status').textContent();
	const alert = await page.locator('#query-results [role="alert"]').textContent();
	const evidence = {
		queryUrl: QUERY_URL,
		valuesPerDimension: VALUES_PER_DIMENSION,
		candidateTriples: VALUES_PER_DIMENSION ** 3,
		rowsWhileBusy: await page.evaluate(() => window.__constructTimeoutRowsWhileBusy),
		responseStatus: response.status,
		contentType: response.contentType,
		capturedStreamStatus: wireResponse.status,
		view: view && view.id,
		streamRows: rows,
		terminal: { type: terminal.type, code: terminal.code, status: terminal.status, message: terminal.message },
		completed: graphTimeoutCompleted,
		status,
		alert,
		countVisible: await result.locator('.query-result-navigation__label').first().isVisible(),
		downloadVisible: await result.locator('.query-result-toolbar__disclosures .workbench-disclosure__toggle')
			.filter({ hasText: 'Download' }).isVisible(),
		busy: await page.locator('#query-results').getAttribute('aria-busy'),
		cancelDisabled: await page.locator('#query-cancel').isDisabled(),
		requestId: await page.locator('#query-request-id').inputValue(),
		pageErrors: monitor.errors
	};
	console.log(`[query-timeout-construct-after-rows] ${JSON.stringify(evidence)}`);
	await testInfo.attach('query-timeout-construct-after-rows.json', {
		body: Buffer.from(JSON.stringify(evidence, null, 2)),
		contentType: 'application/json'
	});
	expect(graphTimeoutCompleted, 'a CONSTRUCT timeout must close its streamed result').toBe(true);
	expect(evidence.rowsWhileBusy).toBeGreaterThan(0);
	expect(view && view.id).toMatch(/graph/);
	expect(rows).toBeGreaterThan(0);
	expect(terminal.type).toBe('error');
	expect(terminal.code).toBe('incomplete');
	expect(terminal.message).toMatch(/visible results are incomplete/i);
	expect(terminal.message).toMatch(/if the query timed out, increase the timeout in Query settings/i);
	expect(terminal.message).not.toMatch(/timed out after 1 second/i);
	expect(records.some(record => record.type === 'end')).toBe(false);
	expect(status).toMatch(/Incomplete results: \d+ rows received before the result stream ended\./);
	expect(alert).toMatch(/increase the timeout in Query settings and run it again\./i);
	expect(alert).not.toMatch(/QueryEvaluationException|EOFException/);
	expect(evidence.countVisible).toBe(false);
	expect(evidence.downloadVisible).toBe(false);
	expect(evidence.busy).toBe('false');
	expect(evidence.cancelDisabled).toBe(true);
	expect(evidence.requestId).toBe('');
	expect(monitor.executions[executionIndex].accept).toContain(NDJSON_ACCEPT);
	expect(monitor.errors).toEqual([]);
	try {
		await result.locator('.query-result-status').scrollIntoViewIfNeeded();
		await testInfo.attach('query-timeout-construct-after-rows.png', {
			body: await page.screenshot(),
			contentType: 'image/png'
		});
	} catch (diagnosticError) {
		console.log(`[query-timeout-construct-screenshot-error] ${String(diagnosticError)}`);
	}
});

function monitorPage(page) {
	const monitor = { errors: [], executions: [], responses: [] };
	page.on('pageerror', error => monitor.errors.push(error.message));
	page.on('request', request => {
		if (request.method() === 'POST' && /\/query(?:[?#]|$)/.test(request.url())
				&& (request.headers().accept || '').includes(NDJSON_ACCEPT)) {
			monitor.executions.push({
				url: request.url(),
				accept: request.headers().accept || '',
				body: request.postData() || ''
			});
		}
	});
	page.on('response', response => {
		const request = response.request();
		if (request.method() !== 'POST' || !/\/query(?:[?#]|$)/.test(request.url())
				|| !(request.headers().accept || '').includes(NDJSON_ACCEPT)) {
			return;
		}
		const entry = {
			url: request.url(),
			status: response.status(),
			contentType: response.headers()['content-type'] || '',
			body: '',
			bodyPromise: Promise.resolve()
		};
		entry.bodyPromise = response.text().then(body => { entry.body = body; }).catch(error => {
			entry.body = `Unable to read response: ${error.message}`;
		});
		monitor.responses.push(entry);
	});
	return monitor;
}

async function installTimeoutDiagnostics(page, browserName) {
	const state = {
		startedAt: new Date().toISOString(),
		browserName,
		pageEvents: [],
		nodeSamples: [],
		rendererEvents: new Array(10000),
		rendererEventCount: 0,
		rendererEventsDropped: 0,
		setupErrors: []
	};
	const recordNodeEvent = (type, details = {}) => {
		state.pageEvents.push({ source: 'node', type, at: new Date().toISOString(), ...details });
		if (state.pageEvents.length > 300) {
			state.pageEvents.shift();
		}
	};
	const delayHistogram = monitorEventLoopDelay({ resolution: 20 });
	delayHistogram.enable();
	state.delayHistogram = delayHistogram;
	let previousCpu = process.cpuUsage();
	const startedAt = process.hrtime.bigint();
	const sampleNodeProcess = () => {
		const cpu = process.cpuUsage(previousCpu);
		previousCpu = process.cpuUsage();
		const memory = process.memoryUsage();
		state.nodeSamples.push({
			elapsedMs: Number(process.hrtime.bigint() - startedAt) / 1e6,
			rssBytes: memory.rss,
			heapUsedBytes: memory.heapUsed,
			heapTotalBytes: memory.heapTotal,
			externalBytes: memory.external,
			cpuUserMs: cpu.user / 1000,
			cpuSystemMs: cpu.system / 1000,
			eventLoopDelayMaxMs: delayHistogram.max / 1e6,
			eventLoopDelayP99Ms: delayHistogram.percentile(99) / 1e6
		});
		delayHistogram.reset();
		if (state.nodeSamples.length > 120) {
			state.nodeSamples.shift();
		}
	};
	state.nodeSampler = setInterval(sampleNodeProcess, 1000);
	state.nodeSampler.unref();

	page.on('dialog', dialog => {
		recordNodeEvent('dialog', { kind: dialog.type(), message: dialog.message().slice(0, 300) });
		// Match Playwright's no-listener behavior: dismiss the dialog so this observer cannot leave it blocking input.
		void dialog.dismiss().then(() => recordNodeEvent('dialog-dismissed', { kind: dialog.type() }))
			.catch(error => recordNodeEvent('dialog-dismiss-failed', { message: String(error).slice(0, 300) }));
	});
	page.on('pageerror', error => recordNodeEvent('pageerror', { message: error.message.slice(0, 500) }));
	page.on('crash', () => recordNodeEvent('page-crash'));
	page.on('close', () => recordNodeEvent('page-close'));
	page.on('request', request => {
		if (request.method() === 'POST' && /\/query(?:[?#]|$)/.test(request.url())) {
			recordNodeEvent('query-request', { method: request.method(), url: request.url().slice(0, 500) });
		}
	});
	page.on('response', response => {
		const request = response.request();
		if (request.method() === 'POST' && /\/query(?:[?#]|$)/.test(request.url())) {
			recordNodeEvent('query-response', {
				status: response.status(),
				contentType: response.headers()['content-type'] || '',
				url: request.url().slice(0, 500)
			});
		}
	});
	page.on('requestfailed', request => {
		if (request.method() === 'POST' && /\/query(?:[?#]|$)/.test(request.url())) {
			recordNodeEvent('query-request-failed', {
				failure: request.failure()?.errorText || '',
				url: request.url().slice(0, 500)
			});
		}
	});
	page.on('console', message => {
		if (message.type() === 'error' || message.type() === 'warning') {
			recordNodeEvent('console', { level: message.type(), message: message.text().slice(0, 500) });
		}
	});

	await page.addInitScript(() => {
		const events = [];
		const heartbeats = [];
		let droppedEvents = 0;
		let previousHeartbeat = performance.now();
		const record = (type, details = {}) => {
			const event = { type, at: performance.now(), ...details };
			if (events.length < 500) {
				events.push(event);
			} else {
				droppedEvents++;
				events.shift();
				events.push(event);
			}
		};
		const targetDetails = target => {
			if (!(target instanceof Element)) {
				return {};
			}
			const execButton = target.closest('#exec');
			const form = target.closest('#query-form');
			return {
				target: `${target.tagName.toLowerCase()}${target.id ? `#${target.id}` : ''}`,
				execButton: Boolean(execButton),
				form: form && form.id,
				className: typeof target.className === 'string' ? target.className.slice(0, 160) : ''
			};
		};
		for (const type of ['pointerdown', 'pointerup', 'mousedown', 'mouseup', 'click', 'submit']) {
			for (const capture of [true, false]) {
				window.addEventListener(type, event => {
					const details = targetDetails(event.target);
					if (!details.execButton && !(type === 'submit' && details.form === 'query-form')) {
						return;
					}
					record(`${capture ? 'capture' : 'bubble'}-${type}`, {
						...details,
						trusted: event.isTrusted,
						defaultPrevented: event.defaultPrevented,
						button: 'button' in event ? event.button : undefined,
						detail: 'detail' in event ? event.detail : undefined
					});
				}, capture);
			}
		}
		window.addEventListener('beforeunload', () => record('beforeunload'));
		window.addEventListener('pagehide', event => record('pagehide', { persisted: event.persisted }));
		window.addEventListener('error', event => record('window-error', {
			message: event.message.slice(0, 500),
			filename: event.filename.slice(-300),
			line: event.lineno
		}));
		window.addEventListener('unhandledrejection', event => record('unhandledrejection', {
			reason: String(event.reason).slice(0, 500)
		}));
		document.addEventListener('visibilitychange', () => record('visibilitychange', {
			visibility: document.visibilityState
		}));

		try {
			new PerformanceObserver(list => {
				for (const entry of list.getEntries()) {
					record('longtask', {
						start: entry.startTime,
						duration: entry.duration,
						attribution: Array.from(entry.attribution || [], item => ({
							name: item.name,
							containerType: item.containerType,
							containerName: item.containerName,
							containerId: item.containerId
						}))
					});
				}
			}).observe({ type: 'longtask', buffered: true });
		} catch (error) {
			record('longtask-observer-unavailable', { message: String(error).slice(0, 300) });
		}

		const observeBusyState = root => {
			record('results-busy-initial', { value: root.getAttribute('aria-busy') });
			new MutationObserver(records => records.forEach(mutation => record('results-busy-change', {
				oldValue: mutation.oldValue,
				value: root.getAttribute('aria-busy')
			}))).observe(root, { attributes: true, attributeFilter: ['aria-busy'], attributeOldValue: true });
		};
		const existingRoot = document.getElementById('query-results');
		if (existingRoot) {
			observeBusyState(existingRoot);
		} else {
			const rootObserver = new MutationObserver(() => {
				const root = document.getElementById('query-results');
				if (root) {
					rootObserver.disconnect();
					observeBusyState(root);
				}
			});
			rootObserver.observe(document, { childList: true, subtree: true });
		}

		window.setInterval(() => {
			const now = performance.now();
			const memory = performance.memory;
			heartbeats.push({
				at: now,
				gapMs: now - previousHeartbeat,
				visibility: document.visibilityState,
				usedJSHeapSize: memory && memory.usedJSHeapSize,
				totalJSHeapSize: memory && memory.totalJSHeapSize,
				jsHeapSizeLimit: memory && memory.jsHeapSizeLimit
			});
			previousHeartbeat = now;
			if (heartbeats.length > 150) {
				heartbeats.shift();
			}
		}, 1000);
		window.__queryTimeoutDiagnostics = {
			events,
			heartbeats,
			get droppedEvents() { return droppedEvents; }
		};
	});

	if (browserName === 'chromium') {
		try {
			state.rendererSession = await page.context().newCDPSession(page);
			state.rendererSession.on('Tracing.dataCollected', ({ value }) => {
				for (const event of value) {
					const details = event.args && event.args.data;
					const longDuration = Number(event.dur) >= 50000;
					if (!longDuration && !['RunTask', 'FunctionCall', 'EventDispatch', 'UpdateLayoutTree',
						'Layout', 'Paint', 'CompositeLayers', 'V8.GCScavenger', 'V8.GCCompactor', 'MajorGC', 'MinorGC',
						'FireAnimationFrame', 'RunMicrotasks'].includes(event.name)) {
						continue;
					}
					state.rendererEvents[state.rendererEventCount % state.rendererEvents.length] = {
						name: event.name,
						category: event.cat,
						phase: event.ph,
						startUs: event.ts,
						durationUs: event.dur,
						pid: event.pid,
						tid: event.tid,
						data: details && {
							functionName: details.functionName,
							scriptName: details.scriptName,
							url: details.url,
							lineNumber: details.lineNumber,
							columnNumber: details.columnNumber,
							type: details.type,
							name: details.name
						}
					};
					state.rendererEventCount++;
				}
			});
			await state.rendererSession.send('Performance.enable');
			await state.rendererSession.send('Tracing.start', {
				categories: 'devtools.timeline,v8,disabled-by-default-v8.gc,blink.user_timing',
				options: 'record-continuously'
			});
			state.tracingStarted = true;

			state.browserSession = await page.context().browser().newBrowserCDPSession();
			const processInfo = await diagnosticCall(state.browserSession.send('SystemInfo.getProcessInfo'), 2000);
			state.browserProcessBefore = processInfo.value && processInfo.value.processInfo;
		} catch (error) {
			state.setupErrors.push(`Chromium diagnostics setup: ${String(error).slice(0, 500)}`);
		}
	}

	return state;
}

async function attachTimeoutDiagnostics(page, testInfo, state) {
	clearInterval(state.nodeSampler);
	await fs.mkdir(testInfo.outputDir, { recursive: true });
	state.eventLoopDelay = {
		maxMs: state.delayHistogram.max / 1e6,
		p99Ms: state.delayHistogram.percentile(99) / 1e6
	};
	state.delayHistogram.disable();
	state.nodeSamples.push({ at: 'after-test', ...process.memoryUsage() });
	try {
		const pageState = await diagnosticCall(page.evaluate(() => {
			const root = document.getElementById('query-results');
			const button = document.getElementById('exec');
			const rect = button && button.getBoundingClientRect();
			return {
				readyState: document.readyState,
				visibility: document.visibilityState,
				activeElement: document.activeElement && {
					tag: document.activeElement.tagName,
					id: document.activeElement.id
				},
				url: location.href,
				busy: root && root.getAttribute('aria-busy'),
				status: root && root.querySelector('.query-result-status')?.textContent,
				requestId: document.getElementById('query-request-id')?.value,
				executeButton: button && {
					disabled: button.disabled,
					ariaDisabled: button.getAttribute('aria-disabled'),
					box: rect && { x: rect.x, y: rect.y, width: rect.width, height: rect.height }
				},
				memory: performance.memory && {
					usedJSHeapSize: performance.memory.usedJSHeapSize,
					totalJSHeapSize: performance.memory.totalJSHeapSize,
					jsHeapSizeLimit: performance.memory.jsHeapSizeLimit
				},
				diagnostics: window.__queryTimeoutDiagnostics && {
					events: window.__queryTimeoutDiagnostics.events,
					heartbeats: window.__queryTimeoutDiagnostics.heartbeats,
					droppedEvents: window.__queryTimeoutDiagnostics.droppedEvents
				}
			};
		}), 1500);
		state.pageState = pageState.value || null;
		state.pageStateError = pageState.error || (pageState.timedOut ? 'page snapshot timed out' : null);

		if (state.tracingStarted && state.rendererSession) {
			let complete;
			const tracingComplete = new Promise(resolve => { complete = resolve; });
			const onTracingComplete = event => complete(event);
			state.rendererSession.on('Tracing.tracingComplete', onTracingComplete);
			state.tracingStarted = false;
			const ended = await diagnosticCall(state.rendererSession.send('Tracing.end'), 1500);
			const trace = await diagnosticCall(tracingComplete, 2000);
			state.tracingComplete = Boolean(trace.value);
			state.tracingEndError = ended.error || (ended.timedOut ? 'Tracing.end timed out' : null);
			state.rendererSession.off('Tracing.tracingComplete', onTracingComplete);
		}
		if (state.rendererSession) {
			const metrics = await diagnosticCall(state.rendererSession.send('Performance.getMetrics'), 1500);
			state.rendererMetrics = metrics.value && metrics.value.metrics;
			state.rendererMetricsError = metrics.error || (metrics.timedOut ? 'Performance.getMetrics timed out' : null);
			const heap = await diagnosticCall(state.rendererSession.send('Runtime.getHeapUsage'), 1000);
			state.rendererHeap = heap.value || null;
			const dom = await diagnosticCall(state.rendererSession.send('Memory.getDOMCounters'), 1000);
			state.rendererDomCounters = dom.value || null;
		}
		if (state.browserSession) {
			const processes = await diagnosticCall(state.browserSession.send('SystemInfo.getProcessInfo'), 1500);
			state.browserProcessAfter = processes.value && processes.value.processInfo;
			state.browserProcessError = processes.error || (processes.timedOut ? 'SystemInfo.getProcessInfo timed out' : null);
		}
	} finally {
		state.sessionDetachErrors = [];
		for (const [name, session] of [['renderer', state.rendererSession], ['browser', state.browserSession]]) {
			if (!session) {
				continue;
			}
			const detached = await diagnosticCall(Promise.resolve().then(() => session.detach()), 750);
			if (detached.error || detached.timedOut) {
				state.sessionDetachErrors.push(`${name}: ${detached.error || 'detach timed out'}`);
			}
		}
	}
	const retainedRendererEventCount = Math.min(state.rendererEventCount, state.rendererEvents.length);
	const firstRetainedIndex = state.rendererEventCount > state.rendererEvents.length
		? state.rendererEventCount % state.rendererEvents.length : 0;
	state.rendererEvents = Array.from({ length: retainedRendererEventCount }, (_, index) =>
		state.rendererEvents[(firstRetainedIndex + index) % state.rendererEvents.length]);
	state.rendererEventsDropped = state.rendererEventCount - retainedRendererEventCount;
	state.nodeSamples = state.nodeSamples.slice(-120);
	const diagnosticsPath = testInfo.outputPath('query-timeout-diagnostics.json');
	const diagnosticsBody = JSON.stringify({
		...state,
		delayHistogram: undefined,
		nodeSampler: undefined,
		rendererSession: undefined,
		browserSession: undefined
	}, null, 2);
	await fs.writeFile(diagnosticsPath, diagnosticsBody);
	await testInfo.attach('query-timeout-diagnostics.json', {
		path: diagnosticsPath,
		contentType: 'application/json'
	});
}

async function diagnosticCall(promise, timeoutMs) {
	return new Promise(resolve => {
		const timer = setTimeout(() => resolve({ timedOut: true }), timeoutMs);
		Promise.resolve(promise).then(value => {
			clearTimeout(timer);
			resolve({ value });
		}, error => {
			clearTimeout(timer);
			resolve({ error: String(error).slice(0, 500) });
		});
	});
}

async function captureQueryResponseBodies(page) {
	await page.addInitScript(acceptType => {
		window.__queryTimeoutCapturedResponses = [];
		const originalFetch = window.fetch.bind(window);
		window.fetch = (input, init) => originalFetch(input, init).then(response => {
			const headers = new Headers(init && init.headers || {});
			if (init && init.method === 'POST' && (headers.get('Accept') || '').includes(acceptType)) {
				const entry = { status: response.status, body: '', complete: false };
				window.__queryTimeoutCapturedResponses.push(entry);
				response.clone().text().then(body => {
					entry.body = body;
					entry.complete = true;
				}).catch(error => {
					entry.body = `Unable to capture response: ${error.message}`;
					entry.complete = true;
				});
			}
			return response;
		});
	}, NDJSON_ACCEPT);
}

/**
 * The NDJSON records of a response captured by captureQueryResponseBodies, parsed in the page; a rows record keeps
 * only its number of rows, so a stream of several hundred thousand rows is not copied out of the browser.
 */
async function capturedStreamRecords(page, index) {
	return page.evaluate(responseIndex => {
		const entry = window.__queryTimeoutCapturedResponses[responseIndex];
		const records = entry.body.split(/\r?\n/).filter(line => line.trim()).map(line => {
			const record = JSON.parse(line);
			if (record.type === 'rows' && Array.isArray(record.values)) {
				record.values = { length: record.values.length };
			}
			return record;
		});
		entry.body = '';
		return records;
	}, index);
}

function repositoryConfiguration(repositoryId) {
	return `@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#>.
@prefix config: <tag:rdf4j.org,2023:config/>.
[] a config:Repository ;
   config:rep.id "${repositoryId}" ;
   rdfs:label "Disposable query timeout fixture" ;
   config:rep.impl [ config:rep.type "openrdf:SailRepository" ;
      config:sail.impl [ config:sail.type "openrdf:MemoryStore" ; config:mem.persist false ] ].`;
}

async function setEditor(page, query) {
	await page.locator('.CodeMirror').first().evaluate((element, value) => {
		element.CodeMirror.setValue(value);
	}, query);
}

function parseNdjson(body) {
	return body.split(/\r?\n/).filter(line => line.trim()).map(line => JSON.parse(line));
}

function valuesIris(prefix, dimension = VALUES_PER_DIMENSION) {
	return Array.from({ length: dimension }, (_, index) => `<urn:${prefix}${index}>`).join(' ');
}

function countRecords(records) {
	return records.reduce((counts, record) => {
		counts[record.type] = (counts[record.type] || 0) + 1;
		return counts;
	}, {});
}

function summarizeRecord(record) {
	if (!record) {
		return null;
	}
	return {
		type: record.type,
		code: record.code,
		status: record.status,
		message: record.message,
		rowCount: record.values ? record.values.length : undefined,
		metadata: record.metadata
	};
}

function summarizeTerminalSafely(body) {
	if (!body || body.startsWith('Unable to read response:')) {
		return null;
	}
	try {
		const records = parseNdjson(body);
		return summarizeRecord(records[records.length - 1]);
	} catch (error) {
		return { parseError: String(error) };
	}
}
